const w = $json;

const SYSTEM = "You write listings for a professional pre-owned and new luxury watch dealer. Write in a confident, accurate, premium tone, native quality for each language (not a word-for-word translation). Only use facts you are given - never invent service history, accessories, or claims of authenticity certification. Title: max 80 characters, brand + model + reference + key feature. Description: 120-200 words, short paragraphs, then a bullet list of specifications you were given. Do not mention the price.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "listings": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "language": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "description": {
            "type": "string"
          }
        },
        "required": [
          "language",
          "title",
          "description"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "listings"
  ],
  "additionalProperties": false
};
const userContent = `Write one listing per language for these language codes: ${w.listing_languages}.
Use the language code in the "language" field.

Dealer: ${w.business_name}
Brand: ${w.brand}
Model: ${w.model || ''}
Reference: ${w.reference}
Year: ${w.year || 'unknown'}
Condition: ${w.condition}
Box and papers: ${w.box_papers ? 'yes, full set' : 'no'}
Watch located in: ${w.location_country || 'unknown'}
Dealer notes: ${w.notes || '-'}`;

return {
  json: {
    claude_request: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      fallbacks: 'default',              // if the model declines, Anthropic retries on a fallback model
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }],
      output_config: {
        effort: 'medium',             // low / medium / high: more effort = better answers, more cost
        format: { type: 'json_schema', schema: SCHEMA },
      },
    },
  },
};

// Read Claude's answer. The answer is JSON because we asked for a JSON schema.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
}
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 500));
}
const ai = JSON.parse(text);

return { json: { watch_id: $('Watches without listings').item.json.id, listings: ai.listings } };

// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

const w = $('Watches without listings').item.json;
const listings = $('Read listings').item.json.listings;
const blocks = listings.map(l => `<h4>[${esc(l.language)}] ${esc(l.title)}</h4><p style="white-space:pre-wrap">${esc(l.description)}</p>`).join('<hr>');
return {
  json: {
    owner_email: w.owner_email,
    from_email: w.from_email,
    subject: `Listings ready: ${w.brand} ${w.reference} (stock #${w.id})`,
    html: `<p>Copy these into your website, Chrono24, eBay or social media.</p>${blocks}`,
  },
};

// When the database query finds nothing, n8n still passes one item: {"success": true}.
// Remove it so the next steps only run for real rows.
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .filter(item => !(Object.keys(item.json).length === 1 && item.json.success === true));
